class Heap:
    def __init__(self):
        self.data = []

    def push(self, item):
        self.data.append(item)
        self._up(len(self.data)-1)

    def _up(self, index):
        parent = (index-1) // 2
        if index and self.data[parent] > self.data[index]:
            self.data[parent], self.data[index] = self.data[index], self.data[parent]
            self._up(parent)

    def pop(self):
        if len(self.data) == 0:
            return None
        result = self.data[0]
        self.data[0] = self.data.pop()
        self._down(0)
        return result

    def _down(self, index):
        left = 2*index + 1
        right = 2*index + 2
        largest = index
        if left < len(self.data) and self.data[left] > self.data[largest]:
            largest = left
        if right < len(self.data) and self.data[right] > self.data[largest]:
            largest = right
        if largest!= index:
            self.data[largest], self.data[index] = self.data[index], self.data[largest]
            self._down(largest)

