from collections import deque

def solve():
    a, b, c, d = map(int, input().split())
    if (d < b) or (c < a):
        return -1
    queue = deque([(a, b, 0)])
    visited = {(a, b)}
    while queue:
        x, y, step = queue.popleft()
        if (x == c) and (y == d):
            return step
        if (x + 1 <= c) and (y + 1 <= d) and ((x + 1, y + 1) not in visited):
            queue.append((x + 1, y + 1, step + 1))
            visited.add((x + 1, y + 1))
        if (x - 1 >= c) and ((x - 1, y) not in visited):
            queue.append((x - 1, y, step + 1))
            visited.add((x - 1, y))

