            bits[j//10][j%10] += (a[j] & 1)
            a[j] >>= 1
        max_val = -1
        min_val = 10**10
        for j in range(n):
            if bits[j//10][j%10]:
                max_val = max(max_val, (j//10)*10 + (j%10))
            if bits[j//10][9-j%10]:
                min_val = min(min_val, (j//10)*10 + (9-j%10))
        if min_val!= 10**10:
            ans = min(ans, max_val-min_val)

    print(ans)

