        return 'NO'

    def helper(max_num):
        cur = 0
        for i in range(n):
            if a[i] <= max_num:
                cur += 1
            else:
                if cur >= k:
                    cur = 0
                else:
                    return 'NO'
        return 'YES'

    def update(max_num, ind):
        if ind == n-1:
            return helper(max_num)

        if ind % 2 == 0:
            min_num = min(a[ind], a[ind+1])
            a[ind] = min_num
            a[ind+1] = min_num
        else:
            max_num = max(a[ind-1], a[ind], a[ind+1])
            a[ind-1] = max_num
            a[ind] = max_num
            a[ind+1] = max_num

        return update(max_num, ind+2)

    return update(1, 0)

